// Reference prime sum
int primeSum(int n) {
    int sum = 0;
    for (int i = 2; i <= n; i++) {
        bool isPrime = true;
        for (int j = 2; j * j <= i; j++) {
            if (i % j == 0) { isPrime = false; break; }
        }
        if (isPrime) sum += i;
    }
    return sum;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        cout << "用法: " << argv[0] << " <考生程序路径>" << endl;
        return 1;
    }
    string progPath = argv[1];

    vector<TestCase> tests = {
        // 样例
        {"10\n",    "17"},
        {"1\n",     "0"},
        {"20\n",    "77"},
        // 小值
        {"2\n",     "2"},
        {"3\n",     "5"},
        {"5\n",     "10"},
        {"7\n",     "17"},
        // 中等值
        {"30\n",    ""},
        {"50\n",    ""},
        {"100\n",   ""},
        // 较大值
        {"200\n",   ""},
        {"500\n",   ""},
        {"1000\n",  ""},
        // 边界
        {"4\n",     ""},
        {"11\n",    ""},
        {"10000\n", ""},
    };

    // Fill in computed expected values
    for (auto& t : tests) {
        if (t.expected.empty()) {
            int n = atoi(t.input.c_str());
            t.expected = to_string(primeSum(n));
        }
    }

    int passed = 0, failed = 0;
    vector<int> failIdx;
    vector<string> failIn, failExp, failAct;

    cout << "========================================" << endl;
    cout << "  编程题2「质数求和」自动测试" << endl;
    cout << "  考生程序: " << progPath << endl;
    cout << "========================================" << endl;
    cout << endl;

    for (int i = 0; i < (int)tests.size(); i++) {
        string actual = runProgram(progPath, tests[i].input);
        if (actual == tests[i].expected) {
            passed++;
            cout << "  测试 #" << (i+1) << ": ✅ 通过" << endl;
        } else {
            failed++;
            failIdx.push_back(i+1);
            failIn.push_back(trim(tests[i].input));
            failExp.push_back(tests[i].expected);
            failAct.push_back(actual);
            cout << "  测试 #" << (i+1) << ": ❌ 未通过" << endl;
        }
    }

    cout << endl;
    cout << "----------------------------------------" << endl;
    cout << "  总计: " << (int)tests.size() << " 个测试" << endl;
    cout << "  通过: " << passed << "  |  未通过: " << failed << endl;
    cout << "----------------------------------------" << endl;

    if (failed > 0) {
        cout << endl;
        cout << "  ❌ 未通过的测试用例详情:" << endl;
        cout << endl;
        printf("  %-6s | %-10s | %-12s | %-12s\n", "编号", "输入(n)", "期望输出", "实际输出");
        printf("  %s\n", "-------+------------+--------------+-------------");
        for (int i = 0; i < failed; i++) {
            printf("  #%-5d | %-10s | %-12s | %-12s\n",
                   failIdx[i], failIn[i].c_str(),
                   failExp[i].c_str(), failAct[i].c_str());
        }
        cout << endl;
    } else {
        cout << endl << "  🎉 全部测试通过！" << endl << endl;
    }

    return failed > 0 ? 1 : 0;
}
